window.__posterData({"id": "zubeyr", "name": "Zubeyr Amale", "folder": "Week_44_Poster_Zubeyr_AI", "v": "2", "scripts": ["https://cdn.jsdelivr.net/npm/p5@2.3.4/lib/p5.js", "https://cdn.jsdelivr.net/npm/p5.sound@0.4.1/dist/p5.sound.min.js"], "links": [], "css": "html, body {\n  margin: 0;\n  padding: 0;\n}\ncanvas {\n  display: block;\n}\n", "code": "// (AI: alla konstanter nedan, så att siffrorna ligger på ett ställe i stället för direkt i koden)\nconst CANVAS_W = 600;\nconst CANVAS_H = 800;\nconst CENTER_X = CANVAS_W / 2;\n\n// Array med tre färger\nconst COLORS = ['#FF0055', '#00FFCC', '#FFE600'];\nconst TEXT_COLOR = COLORS[0];  // (AI: första färgen används som textfärg)\n\n// (AI: bakgrundsfärger som konstanter, svart när ravet är på, annars ljus)\nconst BG_RAVE = 0;\nconst BG_CALM = 240;\n\n// (AI: bildens position och storlek)\nconst IMG = { x: 125, y: 250, size: 350 };\n\n// (AI: cirklarnas placering)\nconst CIRCLE = { startX: 150, spacing: 150, y: 700, size: 80 };\n\n// (AI: hur många frames en \"takt\" är, lägre = snabbare rave)\nconst BEAT_FRAMES = 15;\n\n// (AI: lasrarnas startpunkter, längd, antal strålar och hur snabbt/långt de sveper)\nconst LASER_ORIGINS = [\n  { x: 0, y: 0 },\n  { x: CENTER_X, y: 0 },\n  { x: CANVAS_W, y: 0 },\n];\nconst LASER_LENGTH = 1200;\nconst LASER_BEAMS = 5;\nconst LASER_SWEEP_SPEED = 0.05;\nconst LASER_SWEEP_WIDTH = CANVAS_W / 2;\n\n\n// Variabel för bilden\nlet img;\n\n// Börjar som av (false)\nlet rave = false;\n\n\nasync function setup() {\n  createCanvas(CANVAS_W, CANVAS_H);   // postern storlek är 600x800\n  img = await loadImage('rave.png');  // laddar bilden\n  textAlign(CENTER);                  // centrerar texten\n}\n\n\n// Körs hela tiden. Från (https://p5js.org/reference/p5/draw/)\n// (AI: draw() är uppdelad i mindre funktioner)\nfunction draw() {\n  const beat = getBeat();                // (AI: vilken takt vi är på just nu)\n  const beatColor = getBeatColor(beat);  // (AI: färgen för den här takten)\n\n  drawBackground(beatColor);  // (AI: bakgrunden ligger i en egen funktion)\n  drawLasers(beat);           // (AI: lasrar bakom bilden, som scenljus)\n\n  // Ritar bilden\n  image(img, IMG.x, IMG.y, IMG.size, IMG.size);\n\n  // Ritar cirklarna med denna funktion\n  drawCircles(beat);\n\n  // Titel och namn\n  drawTitle(beatColor);  // (AI: flyttad till en egen funktion)\n\n  // Visar vad nästa klick gör\n  drawHint(beatColor);   // (AI: flyttad till en egen funktion)\n}\n\n\n// Mus klick\nfunction mousePressed() {\n  rave = !rave;  // slår på eller av ravet\n}\n\n\n// (AI: räknar ut vilken takt vi är på, 0, 1, 2, 3 ...)\nfunction getBeat() {\n  return floor(frameCount / BEAT_FRAMES);\n}\n\n// (AI: hur långt in i takten vi är, från 1 precis på slaget ner till 0)\nfunction beatPunch() {\n  return 1 - (frameCount % BEAT_FRAMES) / BEAT_FRAMES;\n}\n\n// (AI: färgen byts varje takt när ravet är på, annars den vanliga textfärgen)\nfunction getBeatColor(beat) {\n  return rave ? COLORS[beat % COLORS.length] : TEXT_COLOR;\n}\n\n// (AI: gör en färg genomskinlig, alpha 0–255)\nfunction withAlpha(hex, alpha) {\n  const c = color(hex);\n  c.setAlpha(alpha);\n  return c;\n}\n\n\nfunction drawBackground(beatColor) {\n  // If-sats: svart bakgrund om ravet är på, annars ljus\n  // (AI: ändrad från if-sats till \"? :\")\n  background(rave ? BG_RAVE : BG_CALM);\n\n  // (AI: tunt färglager i taktens färg som blinkar starkare på slaget)\n  if (rave) {\n    push();\n    noStroke();\n    fill(withAlpha(beatColor, 35 + beatPunch() * 30));\n    rect(0, 0, width, height);\n    pop();\n  }\n}\n\n\n// (AI: hela funktionen. Lasrar som sveper vänster–höger om och om igen när ravet är på)\nfunction drawLasers(beat) {\n  if (!rave) return;\n\n  const punch = beatPunch();\n\n  // (AI: punkten lasrarna siktar på pendlar över postern med sin(), höjden styrs av musen)\n  const targetX = CENTER_X + sin(frameCount * LASER_SWEEP_SPEED) * LASER_SWEEP_WIDTH;\n  const targetY = mouseY;\n\n  push();\n  blendMode(ADD);  // (AI: överlappande ljus blir ljusare, som riktiga lasrar)\n\n  for (let k = 0; k < LASER_ORIGINS.length; k++) {\n    const o = LASER_ORIGINS[k];\n    const c = COLORS[(beat + k) % COLORS.length];  // (AI: varje laser har sin egen färg som byts i takt)\n\n    // (AI: vinkeln från startpunkten till punkten som sveper. Från https://p5js.org/reference/p5/atan2/)\n    const angle = atan2(targetY - o.y, targetX - o.x);\n\n    // (AI: strålarna slår upp brett på slaget och drar ihop sig mellan slagen)\n    const spread = 0.03 + punch * 0.1;\n\n    for (let b = 0; b < LASER_BEAMS; b++) {\n      const a = angle + (b - (LASER_BEAMS - 1) / 2) * spread;\n      const endX = o.x + cos(a) * LASER_LENGTH;\n      const endY = o.y + sin(a) * LASER_LENGTH;\n\n      // (AI: yttre färgad glow, tjockare och starkare på slaget)\n      drawingContext.shadowBlur = 25 + punch * 25;\n      drawingContext.shadowColor = c;\n      stroke(withAlpha(c, 110 + punch * 120));\n      strokeWeight(3 + punch * 4);\n      line(o.x, o.y, endX, endY);\n\n      // (AI: tunn vit kärna i mitten av strålen)\n      drawingContext.shadowBlur = 0;\n      stroke(255, 160 + punch * 95);\n      strokeWeight(1);\n      line(o.x, o.y, endX, endY);\n    }\n\n    // (AI: ljuskälla där lasern skjuts ut)\n    noStroke();\n    fill(withAlpha(c, 200));\n    drawingContext.shadowBlur = 30;\n    drawingContext.shadowColor = c;\n    circle(o.x, o.y, 20 + punch * 20);\n  }\n\n  // (AI: lysande punkt där lasrarna möts, pulserar på slaget)\n  noStroke();\n  fill(255);\n  drawingContext.shadowBlur = 40;\n  drawingContext.shadowColor = COLORS[beat % COLORS.length];\n  circle(targetX, targetY, 10 + punch * 14);\n\n  pop();\n}\n\n\n//  Funktion som ritar tre cirklar. Från (https://p5js.org/reference/p5/function/)\nfunction drawCircles(beat) {\n  // For-loop som körs 3 gånger, en gång per färg\n  // (AI: använder COLORS.length i stället för 3)\n  for (let i = 0; i < COLORS.length; i++) {\n\n    // If-sats: slumpad färg om ravet är på, annars färgen i tur och ordning\n    // (AI: ändrad till \"? :\", och random() är bytt mot färger som roterar i takt)\n    const c = rave ? COLORS[(i + beat) % COLORS.length] : COLORS[i];\n\n    // (AI: cirkeln \"andas\" lugnt, eller pumpar i takt när ravet är på)\n    const pulse = rave\n      ? beatPunch() * 25 + sin(frameCount * 0.3 + i) * 6\n      : sin(frameCount * 0.05 + i) * 4;\n\n    const x = CIRCLE.startX + i * CIRCLE.spacing;\n    const size = CIRCLE.size + pulse;\n\n    push();\n    // (AI: glow-effekt med canvasens skugga)\n    drawingContext.shadowBlur = rave ? 45 : 15;\n    drawingContext.shadowColor = c;\n\n    noStroke();\n    fill(c);\n    circle(x, CIRCLE.y, size);  // cirklarna står bredvid varandra\n\n    // (AI: ring runt cirkeln som växer ut och tonar bort på varje slag)\n    noFill();\n    stroke(withAlpha(c, rave ? 200 * beatPunch() : 90));\n    strokeWeight(3);\n    circle(x, CIRCLE.y, size + 20 + (rave ? (1 - beatPunch()) * 30 : 0));\n    pop();\n  }\n}\n\n\n// Titel och namn\n// (AI: samma färg och glow som cirklarna, och titeln studsar på slaget)\nfunction drawTitle(beatColor) {\n  push();\n  drawingContext.shadowBlur = rave ? 30 : 0;\n  drawingContext.shadowColor = beatColor;\n  fill(beatColor);\n\n  textSize(75 + (rave ? beatPunch() * 8 : 0));\n  text('Scary Hours 🫣', CENTER_X, 120);\n\n  textSize(20);\n  text('BY ZUBEYR', CENTER_X, 170);\n  pop();\n}\n\n\n//   Visar vad nästa klick gör\n// (AI: if/else med två text()-rader ändrad till en rad med \"? :\" och template string)\nfunction drawHint(beatColor) {\n  push();\n  fill(beatColor);\n  textSize(16);\n  text(`[ CLICK MOUSE TO ${rave ? 'STOP' : 'START'} RAVE ]`, CENTER_X, 780);\n  pop();\n}\n\n// Steg 1: Jag bad AI:n refaktorera koden utan att ändra funktionen. Den bytte mina if/else mot “? :” och delade upp draw() i mindre funktioner. Postern såg likadan ut som innan.\n\n// Steg 2: Jag bad den göra draw() bättre och få cirklarna att poppa och matcha bakgrunden och texten. Den lade till glow, pulserande cirklar och en “takt” som gör att allt blinkar och byter färg samtidigt. Den tog också bort min random() på färgerna, vilket jag inte bad om.\n\n// Steg 3: AI:n fick välja en egen funktion och valde laserstrålar som följer musen. Sen bad jag om snabbare och bättre lasrar, och då lade den till fler strålar och en tredje laser. Till sist bad jag att de skulle svepa vänster–höger om och om igen, och då bestämde den själv att musen bara styr höjden.\n\n// Mycket  av det här blev överkurs för mig. Saker som drawingContext, atan2, blendMode och hela takt-systemet har vi inte gått igenom, och jag förstår inte riktigt hur de fungerar. Jag ser vad koden gör när jag kör den, men jag skulle inte kunna skriva den själv. Resultatet blev snyggt, men det känns mindre som min kod nu än innan.", "assets": {"rave.png": {"mime": "image/webp", "b64": ""}}});
